-- Day 15 Speaking: transcribed from the three user-provided topic images.
-- Preserve existing learner attempts and recordings.
insert into public.ark60_content(day_number,module,title,status,payload,published_at,updated_at)
values(15,'speaking','Full Speaking · Day 15','published',$json${"version": "speaking-day-15-v1", "part1": {"topic": "TOPIC 17. HEADPHONES", "questions": [{"key": "p1_q1", "text": "Do you use headphones?"}, {"key": "p1_q2", "text": "In what situations would you use headphones?"}, {"key": "p1_q3", "text": "What type of headphones do you use?"}, {"key": "p1_q4", "text": "In what situations would you NOT use headphones?"}]}, "part2": {"key": "p2_main", "topic": "TOPIC 16. IMPORTANT RIVER", "prompt": "Describe an important river or lake in your country.", "bullets": ["what river it is", "what you know about it", "why it is important"], "max_answer_seconds": 120, "preparation_seconds": 60}, "part3": {"topic": "TOPIC 16. RIVERS AND LAKES", "questions": [{"key": "p3_q1", "text": "Why are rivers and lakes important to local people?"}, {"key": "p3_q2", "text": "How can rivers and lakes benefit the local people?"}, {"key": "p3_q3", "text": "What water sports are popular in your country?"}, {"key": "p3_q4", "text": "Why do people like water sports?"}, {"key": "p3_q5", "text": "Do you think having a river or lake has an impact on tourism in the city?"}, {"key": "p3_q6", "text": "Are rivers and lakes important to a country?"}, {"key": "p3_q7", "text": "Are rivers and lakes good for transport?"}, {"key": "p3_q8", "text": "Do you think rivers and lakes attract tourists?"}]}}$json$::jsonb,now(),now())
on conflict(day_number,module) do update set title=excluded.title,status=excluded.status,payload=excluded.payload,published_at=coalesce(ark60_content.published_at,now()),updated_at=now()
where ark60_content.payload->>'version'='speaking-day-15-v1';
